#include <fcntl.h>
#include <unistd.h>

int	compter_lignes(char *nom)
{
	int		fd;
	int		n;
	int		lus;
	char	buf[64];
	int		i;

	fd = open(nom, O_RDONLY);
	if (fd == -1)
		return (-1);
	n = 0;
	lus = read(fd, buf, 64);
	while (lus > 0)
	{
		i = -1;
		while (++i < lus)
			n += (buf[i] == '\n');
		lus = read(fd, buf, 64);
	}
	close(fd);
	return (n);
}

