void	afficher_mots(t_list *lst)
{
	while (lst != NULL)
	{
		printf("%s\n", (char *)lst->data);
		lst = lst->next;
	}
}

void	empiler(t_list **pile, t_list *nouveau)
{
	nouveau->next = *pile;
	*pile = nouveau;
}

t_list	*depiler(t_list **pile)
{
	t_list	*sommet;

	sommet = *pile;
	if (sommet != NULL)
	{
		*pile = sommet->next;
		sommet->next = NULL;
	}
	return (sommet);
}

unsigned int	hachage(char *cle, unsigned int taille)
{
	unsigned int	h;

	h = 5381;
	while (*cle)
	{
		h = h * 33 + (unsigned char)*cle;
		cle++;
	}
	return (h % taille);
}
